// Why Code: one refresh request per topic: its current plan and the titles of last week's posts its angles caught. Topics that are on are refreshed; a topic that is off is planned only when it has no plan yet, so "on" can start it at once.
const rows = $('Read Topics (Airtable Keywords)').all().flatMap(i => i.json.records || []).filter(r => r.fields.keyword && r.fields.mode)
  .sort((a, b) => String(a.createdTime).localeCompare(String(b.createdTime)));
const posts = $input.all().flatMap(i => i.json.records || []).map(r => r.fields);
const namesOf = (p) => { try { return (JSON.parse(p || '[]') || []).map(a => a.angle).filter(Boolean); } catch (e) { return []; } };
const isQuestion = (k) => /^\s*(what|why|how|which|who|whom|whose|when|where|is|are|was|were|does|do|did|can|could|should|will|would)\b/i.test(k) || /\?\s*$/.test(k);
const count = {}, out = [];
for (const r of rows) {
  // The same numbers as list ds / list ws: all rows of that kind, on and off, by creation date.
  const kind = r.fields.mode === '7days' ? 'ws' : 'ds';
  count[kind] = (count[kind] || 0) + 1;
  const names = namesOf(r.fields.plan), mine = new Set(names), on = r.fields.active === true;
  // The wide angle's posts first: they hold what the narrower angles missed.
  const caught = [...new Set(posts.filter(p => mine.has(p.angle))
    .sort((a, b) => Number(/^all news on/i.test(b.angle)) - Number(/^all news on/i.test(a.angle))).filter(p => p.title).map(p => `${p.angle}: ${p.title}`))].slice(0, 80); // each post with the angle that found it
  if (names.length && (!on || !caught.length)) continue; // off with a plan, or nothing caught: the plan stays as it is
  out.push({ json: { record_id: r.id, keyword: r.fields.keyword, is_question: isQuestion(r.fields.keyword), current_plan: names.length ? r.fields.plan : '',
    caught, label: `${kind} ${count[kind]}`, on } });
}
return out;

// Why Code: pairs each new plan with its topic, keeps only the plans that passed the check, and writes the one Telegram report of what changed.
const reqs = $('Build Refresh Requests').all().map(i => i.json);
const now = new Date().toISOString();
const records = [], lines = [];
$input.all().forEach((it, idx) => {
  const p = it.json || {}, q = reqs[(it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : idx] || {};
  const head = `${q.label}${q.on ? '' : ' (off)'} "${q.keyword}"`;
  if (p.ok !== true) { lines.push(`⚠️ ${head}: not refreshed, the old plan stays (${String(p.reason || (p.error && p.error.message) || p.error || 'no answer').slice(0, 120)})`); return; }
  records.push({ id: q.record_id, fields: { plan: JSON.stringify(p.angles), plan_updated: now } });
  const added = p.added || [], removed = p.removed || [];
  if (!q.current_plan) lines.push(`🆕 ${head}: first plan: ${p.angles.map(a => a.angle).join('; ')}`);
  else if (!added.length && !removed.length) lines.push(`= ${head}: same angles (word lists refreshed)`);
  else lines.push(`🔄 ${head}: ` + [added.length ? '+ ' + added.join('; ') : '', removed.length ? '− ' + removed.join('; ') : ''].filter(Boolean).join(' | '));
});
const text = ['Claim Checks · search plans refreshed', ...lines, '', 'Each topic\'s angles: list ds / list ws'].join('\n').slice(0, 4000);
const out = [];
for (let i = 0; i < records.length; i += 10) out.push({ json: { records: records.slice(i, i + 10), text } });
return out.length ? out : [{ json: { records: [], text } }];
